function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

`reduce` iterates an array and **accumulates a single result** by calling a reducer function with the running accumulator and each element.

```js
const sum = [1, 2, 3, 4].reduce((acc, n) => acc + n, 0);
// acc starts at 0
// 0+1=1, 1+2=3, 3+3=6, 6+4=10
console.log(sum); // 10
```

Common uses: sum, flatten, groupBy, count occurrences.
